const LEGACY_FIELD_IDS=Object.freeze(['grassland','shallow_ford','crosswind_ridge']);
const FIELD_IDS=Object.freeze([...LEGACY_FIELD_IDS,'desert','icefield','highland','rockfield','volcano']);
const STRENGTHS=Object.freeze([4,8,12]);
const CANDIDATE_STRENGTH=4; // Lowest test arm, NOT a selected shipping value.
