    protocol: REACTION_PROTOCOL,
    version: 1,
    mode: REACTION_MODE,
    roomId: event.roomId,
    sessionId: event.sessionId,
    type: REACTION_TYPE,
    roundId: event.roundId,
    emoji: event.emoji,
