  R('fiery_coil_inceptor',{name:'終炎膨張',tag:'膨張・大爆発',description:'傷つくほど膨らみ、倒れると広い範囲に威力上限のある大爆発を起こす。',color:'#ff8b3d',cast:strike,tick(u,c){grow(u,c,1+Math.min(0.5,Math.max(0,1-c.rawHp(u)/c.maxHp(u))*0.5));},death(u,c){fx(u,c,'fire',240,'#ff7b28');c.targets(u,240,24).forEach(t=>c.damage(u,t,Math.min(120,c.power(u,2.2))));}});
  R('golem',{name:'瓦礫の継承',tag:'壁・岩人形',description:'倒れると短時間残る瓦礫の壁になり、小さな岩人形を二体残す。',color:'#bd9b72',cast:strike,death(u,c){c.wall(u,u.x,u.y,{radius:30,duration:300});fx(u,c,'wall',36,'#bd9b72');for(let i=0;i<2;i++)c.spawn(u,'stone_mason',{hp:110,damageMultiplier:0.85,radiusScale:0.8,lifetime:600});}});
  R('bonefan_reaper',{name:'刈魂の大鎌',tag:'処刑・成長',description:'広い鎌で攻撃し、瀕死の敵に追加ダメージを与え、倒すたび五段階まで育つ。',color:'#c8bddb',range:85,cooldown:155,cast(u,t,c){if(!t)return;fx(u,c,'slash',105,'#c8bddb');c.cone(u,t,105,1.2,8).forEach(e=>{const before=c.rawHp(e);c.damage(u,e,c.power(u,before<c.maxHp(e)*0.2?2.5:1),'boss_melee');if(before>0&&c.rawHp(e)<=0){const n=u.bossState.harvest=Math.min(5,(u.bossState.harvest||0)+1);grow(u,c,1+n*0.06,1+n*0.025);}});}});
