function crowdSilhouetteMask(image,source,width,height,color='#fff0bb'){
 if(!(width>0&&height>0)||width>512||height>512||typeof document==='undefined')return null;
 let id=crowdImageIds.get(image);if(!id){id=++crowdImageSerial;crowdImageIds.set(image,id);}
 const key=[id,...source,width,height,color].join(':');let value=crowdMaskCache.get(key);if(value){crowdMaskCache.delete(key);crowdMaskCache.set(key,value);return value.canvas;}
 try{const canvas=typeof OffscreenCanvas==='function'?new OffscreenCanvas(Math.ceil(width)+2,Math.ceil(height)+2):document.createElement('canvas');canvas.width=Math.ceil(width)+2;canvas.height=Math.ceil(height)+2;const g=canvas.getContext('2d');if(!g)return null;
  g.imageSmoothingEnabled=false;g.drawImage(image,...source,0,1,width,height);g.drawImage(image,...source,2,1,width,height);g.drawImage(image,...source,1,0,width,height);g.drawImage(image,...source,1,2,width,height);g.globalCompositeOperation='destination-out';g.drawImage(image,...source,1,1,width,height);g.globalCompositeOperation='source-in';g.fillStyle=color;g.fillRect(0,0,canvas.width,canvas.height);g.globalCompositeOperation='source-over';
  value={canvas,pixels:canvas.width*canvas.height};crowdMaskCache.set(key,value);crowdMaskPixels+=value.pixels;
  while(crowdMaskCache.size>64||crowdMaskPixels>1048576){const k=crowdMaskCache.keys().next().value,q=crowdMaskCache.get(k);crowdMaskCache.delete(k);crowdMaskPixels-=q.pixels;}return canvas;
 }catch{return null;}
}
function drawCrowdSpriteOutline(u,image,source,left,top,width,height){
 // Only the selected body needs an alpha mask; passive viewing adds no sprite blits.
 const e=crowdFocusedEntry;if(e&&e.u===u)e.focusSprite={image,source,left,top,width,height};
}
function drawCrowdHP(u,e){drawSideHPBar(u,e.left,e.top,e.width,4);}
function crowdFocusDetails(){const e=crowdFocusedEntry;if(!e)return null;return {key:e.key,name:TYPES[e.u.k]?.name||e.u.k,kind:e.u.k,side:e.u.side,unit:e.u,hp:Math.max(0,Math.ceil(e.u.hp)),maxHP:bossPresentationMaxHp(e.u)};}
function drawCrowdFocusedHP(){
 const e=crowdFocusedEntry;if(!e)return;const u=e.u,f=e.focusSprite;
 if(f){const mask=crowdSilhouetteMask(f.image,f.source,f.width,f.height);if(mask){ctx.save();ctx.translate(Math.round(u.x),Math.round(u.y)-(LICENSED_CLIP_REGISTRIES[u.k]?0:(MONSTER_META[u.k]?.hover_gap||0)));ctx.scale(visualFor(u).face,1);ctx.drawImage(mask,f.left-1,f.top-1,f.width+2,f.height+2);ctx.restore();}}
 drawSideHPBar(u,e.left,e.top,e.width,4);
 // A selected HP border is also the fallback when its sprite cannot be outlined.
 ctx.save();ctx.strokeStyle='#fff0bb';ctx.lineWidth=2;ctx.strokeRect(e.left-1.5,e.top-1.5,e.width+3,7);ctx.restore();
}

// A final lightweight health-bar pass prevents later sprites from hiding earlier bars.
function drawVisibleHP(u){
 if(u.dead||((u.presentationFlags||0)&2))return;
 const e=crowdFrame.get(u);if(e){drawCrowdHP(u,e);return;}
 const a=crowdHPAnchor(u);drawSideHPBar(u,a.x-14,a.y);
}



let fieldDrawPass='all';const ARENA_FLOOR_ONLY_ASSET="https://gbaconrice.github.io/docchi-ga-katsu/releases/gravity-lazy-v3/images/bf06853b8247b08d2ee2dd4e86295b12990fc37cd1f379893677d497c7bfd9c3.png";const FIELD_FLOORS={"grassland": "https://gbaconrice.github.io/docchi-ga-katsu/releases/gravity-lazy-v3/images/5593ab828f89e0820a8cdc22155add02a607899055aab1f741e9388c40f055f5.webp", "shallow_ford": "https://gbaconrice.github.io/docchi-ga-katsu/releases/gravity-lazy-v3/images/ce8ce8374576d3ac930f096ef87fccf1bd3c07fa2942587bcc43a1ad8e6da25f.webp", "crosswind_ridge": "https://gbaconrice.github.io/docchi-ga-katsu/releases/gravity-lazy-v3/images/ce03ea815ca29e1d291808d95bda9656f532dd1533a3fe758d2cca530b00b8d8.webp"};const FIELD_BORDER="https://gbaconrice.github.io/docchi-ga-katsu/releases/gravity-lazy-v3/images/fec595d8a22e230d193cf3a0598b111954ad0f3d0c1fb6d7595caa7c15d053ef.png";
/** One selected embedded floor; old callbacks cannot redraw a later field. No network URLs. */
function createFieldFloorCache({sources,createImage,onReady=()=>{}}){
 let selected=null,image=null,ready=false,failed=false,epoch=0;
 function release(){if(image){image.onload=null;image.onerror=null;if(image.removeAttribute)image.removeAttribute('src');}image=null;ready=false;}
 return Object.freeze({select(id){if(id===selected)return;epoch++;release();selected=id;failed=false;if(!Object.prototype.hasOwnProperty.call(sources,id))return;const src=sources[id];if(!isGameImageSource(src,'image/webp'))throw Error('embedded-field-source-required');const own=epoch,next=createImage();image=next;next.onload=()=>{if(own!==epoch||image!==next)return;if(next.naturalWidth!==480||next.naturalHeight!==538){failed=true;return;}ready=true;onReady(id);};next.onerror=()=>{if(own===epoch&&image===next){ready=false;failed=true;}};setGameImageSource(next,src);},get(){return ready?image:null;},status(){return{selected,ready,failed,epoch,retainedImages:image?1:0,decodedEstimateBytes:ready?480*538*4:0};},clear(){epoch++;release();selected=null;failed=false;}});
}

let battleEnvironment=null;
const arenaFloorImage=typeof Image!=='undefined'?new Image():null;
if(arenaFloorImage){arenaFloorImage.onload=()=>draw();setGameImageSource(arenaFloorImage,ARENA_FLOOR_ONLY_ASSET);}
let fieldBorderImage=null,fieldBorderReady=false;
Object.assign(FIELD_FLOORS,{"desert":"https://gbaconrice.github.io/docchi-ga-katsu/releases/review-fixes-20261107/images/c79c7430c69f6050ffeb7fab6b25cadac4c72eb57c7cfa082aa2039c633e9e66.webp","icefield":"https://gbaconrice.github.io/docchi-ga-katsu/releases/review-fixes-20261107/images/e563fdc3a46093e40324be7d866428a4120cb7bdf84e2fac44a0545532b429ca.webp","highland":"https://gbaconrice.github.io/docchi-ga-katsu/releases/review-fixes-20261107/images/0797e5372cbaf2ab654b5d431feb0c6f395335ca383c7825a1a583a13f1442f2.webp","rockfield":"https://gbaconrice.github.io/docchi-ga-katsu/releases/review-fixes-20261107/images/b3264bbc46f0ba2ccf8bf63f2381e0c9df94e34a4ba2fefd25060d2265a25c7b.webp","volcano":"https://gbaconrice.github.io/docchi-ga-katsu/releases/review-fixes-20261107/images/c3d23e4be025d2cd325d641c7334d38678715a969a1d7e92cb158221165a1932.webp"});
const fieldFloorCache=createFieldFloorCache({sources:FIELD_FLOORS,createImage:()=>new Image(),onReady:()=>draw()});
function syncArenaField(){if(typeof Image==='undefined')return;const id=battleEnvironment?.fieldId??null;fieldFloorCache.select(id);if(!fieldBorderImage){const im=new Image();fieldBorderImage=im;im.onload=()=>{if(im.naturalWidth===480&&im.naturalHeight===538){fieldBorderReady=true;draw();}};im.onerror=()=>{fieldBorderReady=false;};setGameImageSource(im,FIELD_BORDER);}}
function drawArenaFloorBase(){syncArenaField();const floor=fieldFloorCache.get();ctx.imageSmoothingEnabled=false;if(floor){ctx.drawImage(floor,0,0,480,538);}else if(arenaFloorImage&&arenaFloorImage.complete&&arenaFloorImage.naturalWidth===480){ctx.drawImage(arenaFloorImage,0,0,480,538);}else{ctx.fillStyle='#35463d';ctx.fillRect(0,0,480,538);}}
function drawArenaFrameOnly(){syncArenaField();if(!fieldBorderReady)return;ctx.imageSmoothingEnabled=false;ctx.drawImage(fieldBorderImage,0,0,480,538);}
function drawArenaFloor(){drawArenaFloorBase();drawArenaFrameOnly();}

function drawBossScene(){const pass=typeof fieldDrawPass==='string'&&['all','base','actors'].includes(fieldDrawPass)?fieldDrawPass:'all';if(pass==='all')ctx.clearRect(0,0,480,538);if(pass==='all')drawArenaFloor();else if(pass==='base')drawArenaFloorBase();if(pass!=='base'){const paintUnits=orderedDrawUnits();prepareCrowdPresentation(paintUnits);drawCombatEffects('ground');for(const s of shots)if(s.k==='punchcap_mushroom')drawMushroomTrap(s);for(let u of paintUnits){if(drawSprite(u))continue;if(u.dead)continue;let color=TEAM_HP_BAR_FILL[u.side===0?0:1];ctx.save();ctx.translate(u.x,u.y);ctx.fillStyle='#0c1716aa';ctx.beginPath();ctx.ellipse(1,8,15,8,0,0,7);ctx.fill();ctx.fillStyle=color;ctx.strokeStyle='#f4dfb5';ctx.lineWidth=2;ctx.beginPath();ctx.arc(0,0,13,0,7);ctx.fill();ctx.stroke();ctx.fillStyle='#fff3d7';ctx.font='bold 12px sans-serif';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText({sword:'剣',shield:'盾',spear:'槍',archer:'弓',cannon:'砲',rider:'騎',healer:'癒',goblin:'鬼',golem:'岩',drake:'翼',wraith:'霊'}[u.k],0,0);ctx.restore()}for(const u of paintUnits){drawVisibleHP(u);drawHealingBlockIndicator(u);drawRootIndicator(u);drawGuardIndicator(u);drawExposureIndicator(u);drawBossStatus(u);}drawCrowdFocusedHP();drawCombatEffects('above');ctx.fillStyle='#f4dda1';for(const s of shots){if(s.k==='punchcap_mushroom')continue;if(drawProjectile(s))continue;ctx.beginPath();ctx.arc(s.x,s.y-(s.k==='wraith'?25:16),3,0,7);ctx.fill()}}}

