const shockRegistry=LICENSED_CLIP_REGISTRIES.shockplate_drake;
let shockEpochCounter=0,shockEpoch='shock:initial';const shockHost=ShockHost.createShockHost(shockRegistry,shockEpoch);
function resetShockPresentation(){shockEpoch='shock:opening:'+ ++shockEpochCounter;shockHost.reset(shockEpoch)}
function consumeShockPresentation(){if(units.some(u=>u.k==='shockplate_drake'))shockHost.ingest({epoch:shockEpoch,tick:Math.round(elapsed*60),events:combatEvents,units})}
function shockSample(u,tick,moving=visualFor(u).moving){const v=visualFor(u);return shockHost.sample(u.token,{nowTick:tick,deadAtTick:v.death===null?null:Math.round(v.death*60),hitAtTick:Number.isFinite(v.hit)?Math.round(v.hit*60):null,moving})}
function shockActionFrame(u,tick){if(u.k!=='shockplate_drake'||u.dead)return null;const f=shockSample(u,tick);return f.face===undefined?null:f}
function shockPresentationFrame(u,tick,moving=visualFor(u).moving){return shockSample(u,tick,moving).index}

// Three legal strike-stage events own body presentation; damage events only own impacts.
const comboRegistries=Object.fromEntries(['skullflare_triad','floatinghelm_tripler','quadcut_swordmaster','kilnback_pincerbeast','duskgargoyle_clawer','duskbrown_rat','archclapper_walker','latecut_staffblade','komodo_fiveclaw','shade_trislasher','ringblade_maehv','redshield_tripler','baast_handtripler','dusk_triplewarden','flipthrust_legend','goldstroke_rotator','cyan_tripleblade','crimson_levitator','rex_clawtripler','greenlash_hatmaster','daemonflash_tripler','sunhalo_polyhedron','klaxon_windup_blader','ribwraith_tripler','cyanarm_mystic','ivoryspike_scarab','hatblade_hsuku','locust_pulsefighter','greenflame_triad','crestblade_sentinel','scarlet_bladebeast','crystal_glint_wisp','ringneck_prowler','gauntlet_combo_guard','azure_blade_trio','carapace_slashbeast'].map(k=>[k,LICENSED_CLIP_REGISTRIES[k]]));
let comboEpochCounter=0,comboEpoch='combo:initial';const comboHosts=Object.fromEntries(Object.entries(comboRegistries).map(([k,v])=>[k,TYPES[k].comboStageContacts ? FixedStageComboPresentation.createFixedStageComboPresentation(v,comboEpoch,FixedStageComboPresentation.fixedStageProfileFromSourceSpec(LICENSED_CLIP_SPECS[k])) : ComboPresentation.createComboPresentation(v,comboEpoch)]));const comboHost=comboHosts.gauntlet_combo_guard;
function resetComboPresentation(){comboEpoch='combo:opening:'+ ++comboEpochCounter;Object.values(comboHosts).forEach(h=>h.reset(comboEpoch))}
function consumeComboPresentation(){for(const[k,h]of Object.entries(comboHosts))if(units.some(u=>u.k===k))h.ingest({epoch:comboEpoch,tick:Math.round(elapsed*60),events:combatEvents,units})}
function comboSample(u,tick,moving=visualFor(u).moving){const v=visualFor(u);return comboHosts[u.k].sample(u.token,{nowTick:tick,deadAtTick:v.death===null?null:Math.round(v.death*60),hitAtTick:Number.isFinite(v.hit)?Math.round(v.hit*60):null,moving})}
function comboActionFrame(u,tick){if(!comboRegistries[u.k]||u.dead)return null;const f=comboSample(u,tick);return f.face===undefined?null:f}
function comboPresentationFrame(u,tick,moving=visualFor(u).moving){return comboSample(u,tick,moving).index}

// Actual one-sweep event owns the body; per-target cone hits cannot restart it.
const cleaveRegistries=Object.fromEntries(['abyssal_palmweaver','redcrescent_sentinel','desert_flarebeast','spinning_tailbeast','crescent_blade_dancer','branchsweep_treant'].map(k=>[k,LICENSED_CLIP_REGISTRIES[k]]));
let cleaveEpochCounter=0,cleaveEpoch='cleave:initial';const cleaveHosts=Object.fromEntries(Object.entries(cleaveRegistries).map(([k,v])=>[k,CleavePresentation.createCleavePresentation(v,cleaveEpoch)]));const cleaveHost=cleaveHosts.spinning_tailbeast;
function resetCleavePresentation(){cleaveEpoch='cleave:opening:'+ ++cleaveEpochCounter;Object.values(cleaveHosts).forEach(h=>h.reset(cleaveEpoch))}
function consumeCleavePresentation(){for(const[k,h]of Object.entries(cleaveHosts))if(units.some(u=>u.k===k))h.ingest({epoch:cleaveEpoch,tick:Math.round(elapsed*60),events:combatEvents,units})}
function cleaveSample(u,tick,moving=visualFor(u).moving){const v=visualFor(u);return cleaveHosts[u.k].sample(u.token,{nowTick:tick,deadAtTick:v.death===null?null:Math.round(v.death*60),hitAtTick:Number.isFinite(v.hit)?Math.round(v.hit*60):null,moving})}
function cleaveActionFrame(u,tick){if(!cleaveRegistries[u.k]||u.dead)return null;const f=cleaveSample(u,tick);return f.face===undefined?null:f}
function cleavePresentationFrame(u,tick,moving=visualFor(u).moving){return cleaveSample(u,tick,moving).index}

// Wing is phase-owned. No generic cooldown/contact anticipation after cancel or before action.
const wingRegistries=Object.fromEntries(['twinpulse_mage','deathknell_cutpillar','metaltooth_duelist','icy_dualslasher','goldgreatsword_duelist','goldtrident_duelist','redhorn_dualbeast','cyan_multiblade','plated_dualdragon','goldring_brawler','pteryx_tailwing','darkfan_clawlord','cyanspike_commander','fenrir_dualguard','twinmoon_pontiff','redpole_warrior','shieldmace_companion','whiteburst_pugilist','stormhorn_tripler','veteran_flamewing','bluepole_mogwai','specterclaw_shuffler','bubbleclaw_plaguer','spinthrust_grincher','moonclaw_werewolf','wheelblade_knight','windcloth_duelist','wingblade_duelist','feral_fistfighter','triad_chimera','razorclaw_reaver'].map(k=>[k,LICENSED_CLIP_REGISTRIES[k]]));
let wingEpochCounter=0,wingEpoch='wing:initial';const wingHosts=Object.fromEntries(Object.keys(wingRegistries).map(k=>[k,WingHost.createWingHostAdapter(MultiContactClips.compileMultiContact(LICENSED_CLIP_SPECS[k]),wingEpoch)]));const wingHost=wingHosts.wingblade_duelist;
function resetWingPresentation(){wingEpoch='wing:opening:'+ ++wingEpochCounter;Object.values(wingHosts).forEach(h=>h.reset(wingEpoch))}
function consumeWingPresentation(){for(const[k,h]of Object.entries(wingHosts))if(units.some(u=>u.k===k))h.consumeBatch({epoch:wingEpoch,tick:Math.round(elapsed*60),events:combatEvents,units})}
function wingSample(u,tick,moving=visualFor(u).moving){const v=visualFor(u);return wingHosts[u.k].sample(u.token,{nowTick:tick,deadAtTick:v.death===null?null:Math.round(v.death*60),hitAtTick:Number.isFinite(v.hit)?Math.round(v.hit*60):null,moving})}
function wingActionFrame(u,tick){if(!wingRegistries[u.k]||u.dead)return null;const f=wingSample(u,tick);return f.face===undefined?null:f}
function wingPresentationFrame(u,tick,moving=visualFor(u).moving){return wingSample(u,tick,moving).index}

// Host-only bounded action timeline. Guests use canonical pose/face rows.
const wave4Registries=Object.fromEntries(['ringfall_chakkram','spectralhand_wizard','redbud_blightbeast','origami_wingburst','shellburst_arcade','accretion_burstcore','twinflare_fox','sunbreak_pillar_guardian','flameburst_mythron','cyanrise_silithar','groundprism_windmiller','redcore_burstshrine','greenneck_burster','golden_whirlshaper','colossal_hornfist','stonepulse_kolossus','antlerwhirl_myriad','fiery_coil_inceptor','whitehair_spinblade','inkorb_caster','silverarm_vanguard','spikeburst_grinder','thornspin_ooze','emberfist_pillarer','gilded_hopper','flamering_magus','shellpulse_beast','bluehorn_invoker','bastion_stag','basalt_titan','bone_crown_lich','sweep_acolyte','pillar_hammerer','oni_wavelet','goldring_core','tendril_revenant'].filter(k=>LICENSED_CLIP_REGISTRIES[k]).map(k=>[k,LICENSED_CLIP_REGISTRIES[k]]));
let wave4EpochCounter=0,wave4Epoch='wave4:initial';
const wave4Host=After75Host.createAfter75PhaseHost({registries:wave4Registries});wave4Host.reset(wave4Epoch);
