 silverflare_archer:['arrow','#44415c','#d8ca9f','#fff8dd'],
 golden_bowling:['pellet','#62422a','#e6ba4b','#fff1ad'],
 brass_flareslinger:['bolt','#164f56','#62e2c3','#ecfff1'],
