function paintSparkGlyph(c){const g=GUIDED_FLIGHT_CONTRACT.spark_bird.optional_code_native_glyph;for(let y=0;y<5;y++)for(let x=0;x<5;x++){const color=g.rows[y][x];if(color!=='0'){c.fillStyle=g.palette[color];c.fillRect(x,y,1,1)}}}
