// One cached code-native arrow BODY; no trail/path or extra actual entity.
let cinderArrowCanvas=null,cinderArrowAttempted=false;
function paintCinderArrow(c){const g=GUIDED_FLIGHT_CONTRACT.cinderbow_archer;for(let y=0;y<5;y++)for(let x=0;x<9;x++){const color=+g.mask[y][x];if(color){c.fillStyle=g.palette[color];c.fillRect(x,y,1,1)}}}
