  if(!multiAdapter){const sdk=await loadNativeSDK();if(request!==roomEntryGeneration)return;multiAdapter=await SDKAdapter.install({sdk,nonce:()=>crypto.randomUUID(),sessionFactory:MultiBinding.createWalletSession,onReaction:(sender,wire)=>receiveReaction(sender,wire),onSessionReset:adoptRestartedMultiSession,onProfilesChange:refreshNativeProfileViews,sessionOptions:{onChange:receiveNativeMultiChange,requireEnvironment:true}});}
