  const refresh=()=>{if(state==='choose'&&screenMode==='game'&&(!multiSession||multiSnapshot?.phase==='predict')){drawArmyPreviews();assetRefreshUI();}};
  image.onload=()=>{if(image!==predictionBossMarkerImage)return;predictionBossMarkerStatus=image.naturalWidth>=1106&&image.naturalHeight>=1118?'ready':'error';refresh();};
  image.onerror=()=>{if(image!==predictionBossMarkerImage)return;predictionBossMarkerStatus='error';refresh();};
  image.crossOrigin='anonymous';image.src=PREDICTION_BOSS_MARKER_SOURCE;
