 if(predictionBossMarkerStatus==='ready'&&predictionBossMarkerImage?.complete){
  p.drawImage(predictionBossMarkerImage,...PREDICTION_BOSS_MARKER_RECT,x-width/2,top,width,size);return;
 }
 // A failed optional PNG never hides the classification or blocks betting.
 p.save();p.translate(x-width/2,top);p.scale(width/20,size/22);
