  const p=el.getContext('2d');if(!p)continue;const box=el.getBoundingClientRect();if(!(box.width>0&&box.height>0))continue;
  const groups=[];for(const u of units.filter(u=>u.side===side&&!u.dead)){const prior=groups.find(g=>g.k===u.k);if(prior)prior.count++;else groups.push({k:u.k,count:1});}
