   const frame=licensed?.clips.idle.frames[0],img=licensed?licensedImageForFrame(g.k,frame):legacyImage(monster?g.k+'_'+(side?'blue':'red'):(side?'blue':'red')+(exp?'Expansion':''));
   const bodyReady=!!(img&&img.complete&&img.naturalWidth);
   if(bodyReady){p.save();p.translate(g.x,y);p.scale((side?-1:1)*scale,scale);if(licensed){if(frame)p.drawImage(img,...frame.rect,-anchor[0]*bodyScale,-anchor[1]*bodyScale,frame.rect[2]*bodyScale,frame.rect[3]*bodyScale);}else p.drawImage(img,0,(monster?0:SPRITE_ROWS[g.k])*cell,cell,cellH,-anchor[0],-anchor[1],cell,cellH);p.restore();}else drawPredictionPreviewPlaceholder(p,g.x,y,side,g.slotWidth);
   if(TYPES[g.k].boss){const markerSize=Math.min(22,Math.max(1,g.slotWidth-6));drawPredictionBossMarker(p,g.x,(bodyReady?y-g.insets[1]*scale:y-16)-markerSize-4,markerSize);}
