let publicRoomRequest=0;
function parsePublicRooms(result){
 if(result?.errno!==0||!Array.isArray(result.data?.list))throw Error('invalid-public-room-list');
 return result.data.list.map(r=>{
  const id=typeof r?.room_id==='string'?r.room_id:'';
  if(!id||id.length>128||/[\u0000-\u001f\u007f-\u009f]/.test(id)||!Number.isInteger(r.max_players)||r.max_players<1||!Number.isInteger(r.gamer_num)||r.gamer_num<0||r.gamer_num>r.max_players)throw Error('invalid-public-room');
  return {id,count:r.gamer_num,max:r.max_players};
 });
}
async function refreshPublicRooms(){
 if(screenMode!=='room'||multiSession)return;
 const seq=++publicRoomRequest, list=document.querySelector('#publicRoomsList'),status=document.querySelector('#publicRoomsStatus'),refresh=document.querySelector('#refreshPublicRooms');
 list.replaceChildren();status.textContent='取得中…';refresh.disabled=true;
 // Bound the entire lookup, including SDK loading and a native bridge that never replies.
 // Do not cancel the shared SDK load: room creation/joining may be using it too.
 let lookupTimer,expired=false;
 const isCurrent=()=>!expired&&seq===publicRoomRequest&&screenMode==='room'&&!multiSession;
 try {
  const timeout=new Promise((_,reject)=>{lookupTimer=setTimeout(()=>{expired=true;reject(Error('public-rooms-timeout'));},8000);});
  const lookup=(async()=>{
   const sdk=await loadNativeSDK();
   if(!isCurrent())return null;
   if(typeof sdk.room.getPublicRoomList!=='function')throw Error('unavailable');
   return parsePublicRooms(await sdk.room.getPublicRoomList());
  })();
  const rooms=await Promise.race([lookup,timeout]);
  if(!isCurrent()||!rooms)return;
  status.textContent=rooms.length?'公開ルーム '+rooms.length+'件。進行状況は参加後に確認できます。':'公開ルームはありません。';
  for(const room of rooms){
   const button=document.createElement('button');button.type='button';button.className='public-room-item';
   button.textContent=room.id+'  '+room.count+'/'+room.max+'人 '+(room.count>=room.max?'満員':'空きあり');button.disabled=room.count>=room.max;
   button.onclick=()=>{if(multiBusy||multiSession)return;document.querySelector('#roomId').value=room.id;void enterNative('join').then(()=>{if(multiSession){publicRoomRequest++;document.querySelector('#publicRooms').hidden=true;}});};
   list.appendChild(button);
  }
 }catch(error){if(seq===publicRoomRequest&&screenMode==='room'&&!multiSession)status.textContent=error?.message==='public-rooms-timeout'?'接続がタイムアウトしました。GRAVITY内で開くか、更新で再試行してください。':'公開ルーム一覧を取得できませんでした。更新をお試しください。';}
 finally{clearTimeout(lookupTimer);if(seq===publicRoomRequest)refresh.disabled=false;}
}
document.querySelector('#refreshPublicRooms').onclick=()=>void refreshPublicRooms();
document.querySelector('#showMultiplayer').onclick=()=>{if(!walletState)freshWallet();showScreen('room');if(!multiSession)void refreshPublicRooms();};
