function crowdInspectionAvailable(){return screenMode==='game'&&(state==='fight'||state==='result')&&!multiRecording&&(!multiSession||!!multiPlayback);}
function crowdLiveChoices(){return units.filter(crowdLive).sort((a,b)=>{const ak=crowdKey(a),bk=crowdKey(b);return a.side-b.side||(ak<bk?-1:ak>bk?1:0);});}
