 if(!crowdInspectionAvailable())return;const pool=crowdChoicePool();if(!pool.length){redrawCrowdSelection();return;}
 const current=pool.findIndex(u=>crowdKey(u)===crowdFocusKey),index=current<0?(direction<0?pool.length-1:0):(current+direction+pool.length)%pool.length;
 setCrowdFocus(pool[index].token??pool[index].id);redrawCrowdSelection();
