 if(!crowdInspectionAvailable())return;const point=crowdCanvasPoint(e);if(!point)return;
 const hits=crowdHitCandidates(point),keys=hits.map(crowdKey);
 if(!hits.length){clearCrowdSelection();return;}
 const same=crowdChoiceMode==='tap'&&keys.length===crowdCandidateKeys.length&&keys.every(k=>crowdCandidateKeys.includes(k));
 if(same&&crowdCandidateKeys.includes(crowdFocusKey)){
  const nextKey=crowdCandidateKeys[(crowdCandidateKeys.indexOf(crowdFocusKey)+1)%crowdCandidateKeys.length],next=hits.find(u=>crowdKey(u)===nextKey);
  setCrowdFocus(next.token??next.id);redrawCrowdSelection();return;
 }
 crowdChoiceMode='tap';crowdCandidateKeys=keys;setCrowdFocus(hits[0].token??hits[0].id);redrawCrowdSelection();
