cameraCanvas.addEventListener?.('pointerleave',()=>{crowdTap=null;});
if(typeof window!=='undefined')window.addEventListener?.('blur',()=>{crowdTap=null;});
document.addEventListener?.('visibilitychange',()=>{if(document.hidden)crowdTap=null;});
// Keyboard inspection does not steal page scrolling or camera gestures.
cameraCanvas.setAttribute?.('tabindex','0');cameraCanvas.setAttribute?.('aria-describedby','crowdFocusName crowdFocusHP');
