 if(!starts.length)return;starts.sort((a,b)=>b.priority-a.priority||a.tick-b.tick||String(a.token).localeCompare(String(b.token)));const selected=starts[0];if(selected.tick-spectacleLastWindupTick<43)return;spectacleLastWindupTick=selected.tick;spectacleAnimate('#combatSpectacle','windup',selected.event,82,210);
