function terminalWinnerSide(){if(multiSession){const w=multiSnapshot?.winner;return w==='A'||w===0?0:w==='B'||w===1?1:null;}return winner===0||winner===1?winner:null;}
// The current authoritative protocol provides resolved_hit amounts, but no
