function terminalLethalHit(){return null;}
function validDoubleUpWin(entry){if(round<=TOTAL_ROUNDS||!validOwnSettlement(entry)||entry.correct!==true)return false;try{const before=Money.amountBig(entry.balanceBefore),stake=Money.amountBig(entry.stake),delta=Money.signedBig(entry.delta),after=Money.amountBig(entry.balanceAfter);return before>0n&&stake===before&&delta===stake&&after===before*2n}catch{return false}}
