const EARNED_COUNT_MS=1400,BALANCE_RAMP_MS=350;
// Display-only balance: held at the pre-round value while the count-up runs, then eased to the settled value as the coins land.
// The ledger, wallet and wire data are never touched; any exit path restores the exact settled text.
function heldBalanceValue(scene){
 const e=scene.entry;if(!scene.balanceHold||!e)return null;
 const before=Money.amountBig(e.balanceBefore),after=Money.amountBig(e.balanceAfter),p=Math.max(0,Math.min(1,Number.isFinite(scene.rampProgress)?scene.rampProgress:0));
 if(p>=1)return null;
 return p<=0?before:before+(after-before)*BigInt(Math.floor(p*1000))/1000n;
}
// The display may be overwritten only while this scene's own result round is still on screen.
function heldBalanceOwned(scene){try{return !!scene&&personalResultScene===scene&&state==='result'&&scene.key===audioBattleKey()+':'+personalViewerId();}catch(_){return false}}
function applyHeldBalance(scene){
 const node=document.querySelector('#balance');if(!node||!scene)return;
 if(!heldBalanceOwned(scene)){scene.balanceHold=false;scene.heldText=undefined;return;}
 let v=null;try{v=heldBalanceValue(scene)}catch(_){v=null}
 if(v===null){releaseHeldBalance(scene);return;}
 const text=walletBalanceText(v);if(node.textContent!==text)node.textContent=text;scene.heldText=text;
}
function releaseHeldBalance(scene){
 if(!scene||!scene.balanceHold&&scene.heldText===undefined)return;
 const node=document.querySelector('#balance');scene.balanceHold=false;
 // Only restore while this scene's round is still shown (key/state, not text equality): a newer round that happens to show the same text is never overwritten.
 if(node&&scene.heldText!==undefined&&heldBalanceOwned(scene)){try{node.textContent=walletBalanceText(Money.amountBig(scene.entry.balanceAfter))}catch(_){}}
 scene.heldText=undefined;
}
function syncEarnedCount(scene,entry,elapsed){
 const delta=ownPositiveDelta(entry);if(!delta||!scene.earnedRevealed)return;
 const q=id=>document.querySelector(id),node=q('#breakdown');if(!node)return;
 // Ease out for EARNED_COUNT_MS from the frame that really revealed the gain (same clock as coin flight, deposit SE and balance ramp); only the display is interpolated.
 const linear=scene.reducedMotion||scene.cancelled?1:Math.max(0,Math.min(1,(elapsed-(Number.isFinite(scene.stage2At)?scene.stage2At:elapsed))/EARNED_COUNT_MS));
 const progress=1-(1-linear)*(1-linear);
 const text=MoneyUI.resultCountupText(delta,progress);if(node.textContent!==text)node.textContent=text;
 scene.countComplete=progress>=1;setEarnedStage(true,scene.arrivalDone?'arrived':scene.countComplete?'counted':'counting');
}
function syncPersonalResult(now){
 const q=id=>document.querySelector(id),visible=state==='result'&&screenMode==='game'&&!multiRecording;
 if(!multiSession)q('#multiResults').hidden=true;
 if(!visible){cancelPersonalResult();q('#gameScreen')?.setAttribute('data-personal-result','false');hideEarnedFlight();return;}
 const key=audioBattleKey()+':'+personalViewerId(),entry=ownResultEntry();
 if(!personalResultScene||personalResultScene.key!==key){
  cancelPersonalResult();const seen=personalResultSeen.has(key);personalResultSeen.add(key);if(personalResultSeen.size>40)personalResultSeen.delete(personalResultSeen.values().next().value);
  personalResultScene={key,resultStart:null,sequenceStart:null,stage:0,cancelled:seen||document.hidden===true||!!(multiSession&&!multiPlayback),animations:[],entry:null,earnedRevealed:false,countComplete:false,flightStarted:false,flightAttempted:false,flightActive:false,arrivalDone:false,reducedMotion:false,resolveStarted:false,doubleUpShown:false,balanceHold:false,holdDecided:false,rampStart:null,rampProgress:0,coinsFlying:false,heldText:undefined};
 }
 const scene=personalResultScene;
 if(!scene.entry&&validOwnSettlement(entry))scene.entry=entry;
 if(scene.entry&&!scene.holdDecided){scene.holdDecided=true;scene.balanceHold=ownPositiveDelta(scene.entry)>0n&&!scene.cancelled&&!resultReducedMotion();}
 const ownEntry=scene.entry,delta=ownPositiveDelta(ownEntry);
 const participant=!!multiSession&&Array.isArray(multiSnapshot?.participants)&&multiSnapshot.participants.includes(multiUser);
 const awaitingEntry=participant&&!ownEntry;
 const outcome=multiSession?multiSnapshot?.winner:winner===null?'draw':winner===0?'A':'B';
 const label=awaitingEntry?'':ownEntry?.correct===true?'':ownEntry?.correct===false?'':outcome==='draw'?'引き分け':outcome==='invalid'?'無効':'';
 if(q('#message'))q('#message').textContent=label;
 if(q('#breakdown')){
  if(awaitingEntry)q('#breakdown').textContent='';
  else if(!validOwnSettlement(ownEntry))q('#breakdown').textContent='—';
  else if(delta>0n&&!scene.cancelled&&!scene.earnedRevealed&&!resultReducedMotion())q('#breakdown').textContent=MoneyUI.resultCountupText(delta,0);
  else if(delta<=0n||!scene.earnedRevealed||scene.cancelled)q('#breakdown').textContent=credits(ownEntry.delta);
 }
 if(q('#resultWinner')){q('#resultWinner').textContent=outcome==='A'?'左の勝利':outcome==='B'?'右の勝利':'';q('#resultWinner').setAttribute('data-winner',outcome==='A'||outcome==='B'?outcome:'neutral');}
 if(q('#resultRanking')){const finals=multiSession?MoneyUI.rankedByBalance((multiSnapshot.wallets||[]).filter(p=>p.cashedOut===true&&p.cashoutAmount!==null)):[];q('#resultRanking').hidden=!finals.length;q('#resultRanking').textContent=finals.map(p=>(p.playerId===multiUser?'あなた':p.playerId)+' '+MoneyUI.balanceText(p.cashoutAmount)).join(' · ');}
 q('#gameScreen')?.setAttribute('data-personal-result','true');q('#gameScreen')?.setAttribute('data-field-view','true');
 q('#resultPanel')?.setAttribute('data-final',String(round>=sessionRoundLimit()||soloTerminalBoundary()));
 q('#resultPanel')?.setAttribute('data-outcome',awaitingEntry?'pending':ownEntry?.correct===true?'hit':ownEntry?.correct===false?'miss':'neutral');
 const doubleUpWin=validDoubleUpWin(ownEntry);q('#resultPanel')?.setAttribute('data-double-up',String(doubleUpWin));
 const doubleBadge=q('#doubleUpBadge');if(doubleBadge)doubleBadge.hidden=!(doubleUpWin&&scene.earnedRevealed);
 setEarnedStage(delta>0n,delta>0n?(scene.arrivalDone?'arrived':scene.countComplete?'counted':scene.earnedRevealed?'counting':'waiting'):'none');
 // Keep the final canonical field visible; never fabricate a missing guest replay.
 q('#battle').hidden=!!multiSession&&!multiReplay;
 syncStableBattleClock();syncOwnBattleChoice();for(const id of ['#unitsToggle','#reactionToggle','#pause'])if(q(id)){q(id).hidden=id==='#unitsToggle';q(id).disabled=id==='#pause'?!pauseControlAvailable():id==='#reactionToggle'?!reactionLive():!flowControlsAvailable();}
 if(document.hidden===true){cancelPersonalResult();return;}if(scene.balanceHold&&!scene.cancelled)applyHeldBalance(scene);if(!Number.isFinite(now))return;
 if(scene.resultStart===null)scene.resultStart=now;
 const resultElapsed=Math.max(0,now-scene.resultStart);updateResultClipTail(key,resultElapsed);syncBattleAudio();
 if(scene.cancelled){finishEarnedDisplay(scene);return;}
 if(!scene.resolveStarted)startTerminalResolve(scene,now);
 syncTerminalResolve(scene,now);
 if(!awaitingEntry&&scene.sequenceStart===null){scene.sequenceStart=now;scene.reducedMotion=resultReducedMotion();}
 if(awaitingEntry||scene.sequenceStart===null)return;
 const elapsed=Math.max(0,now-scene.sequenceStart),activeEntry=scene.entry,activeDelta=ownPositiveDelta(activeEntry);
 const advance=(stage,at,fn)=>{if(scene.stage<stage&&elapsed>=at){const result=fn();if(result!==false)scene.stage=stage;}};
 advance(1,120,()=>{audioCall(()=>battleAudio.playResultStage(audioBattleKey(),'stamp'));resultAnimate('#message',[{opacity:.45,transform:'scale(.88)'},{opacity:1,transform:'scale(1.04)'},{opacity:1,transform:'scale(1)'}],{duration:420,easing:'ease-out'});});
 advance(2,500,()=>{
  // Preserve canonical decimal strings for extended double-up balances; the
  // audio layer compares them exactly instead of coercing through Number.
  if(validOwnSettlement(activeEntry))audioCall(()=>battleAudio.playResultStage(audioBattleKey(),'delta',{
   delta:activeEntry.delta,stake:activeEntry.stake,balanceBefore:activeEntry.balanceBefore,isDoubleUp:round>TOTAL_ROUNDS
  }));
  if(validOwnSettlement(activeEntry)&&activeEntry.correct!==null)scatterResultCoins(scene,q('#breakdown'),activeEntry);
  scene.stage2At=elapsed; // flight start, SE and cleanup all key off the frame that really started them
  if(activeDelta>0n&&!scene.coinsFlying)releaseHeldBalance(scene); // no visible wallet/room for the flight: show the settled balance now
   if(activeDelta>0n){scene.earnedRevealed=true;syncEarnedCount(scene,activeEntry,elapsed);
   if(doubleUpWin&&q('#doubleUpBadge')){q('#doubleUpBadge').hidden=false;if(!scene.doubleUpShown){scene.doubleUpShown=true;resultAnimate('#doubleUpBadge',[{transform:'translateY(4px) scale(.72)',opacity:0},{transform:'translateY(-1px) scale(1.12)',opacity:1,offset:.58},{transform:'translateY(0) scale(1)',opacity:1}],{duration:230,easing:'steps(4,end)'});}}
  }

 });
 if(activeDelta>0n){
  syncEarnedCount(scene,activeEntry,elapsed);

 }
 // Deposit SE, balance flash and 'arrived' wait for the count-up to finish (not its first frame); reduced motion has no count.
 // Arrival exists only for coins that really took off: landing = their real start + flight time. Reduced motion has no flight (cue at once); otherwise no flight means no arrival cue.
 const arrivalAt=scene.stage<2?Infinity:scene.coinsFlying?scene.stage2At+EARNED_COUNT_MS:scene.reducedMotion?scene.stage2At:Infinity;
 advance(3,arrivalAt,()=>{
  if(activeDelta<=0n)return;

  scene.arrivalDone=true;
  setEarnedStage(true,scene.countComplete?'arrived':'counting');
  if(validOwnSettlement(activeEntry)&&activeEntry.correct===true)audioCall(()=>battleAudio.playResultStage(audioBattleKey(),'balance',{
   delta:activeEntry.delta,stake:activeEntry.stake,balanceBefore:activeEntry.balanceBefore,isDoubleUp:round>TOTAL_ROUNDS
  }));
  animateBalanceArrival(scene);
  if(scene.balanceHold)scene.rampStart=elapsed;
 });
 if(scene.balanceHold&&scene.rampStart!==null){const l=Math.max(0,Math.min(1,(elapsed-scene.rampStart)/BALANCE_RAMP_MS));scene.rampProgress=1-(1-l)*(1-l);}
 if(scene.balanceHold)applyHeldBalance(scene);
 if(scene.flightActive&&scene.stage>=2&&elapsed>=scene.stage2At+(EARNED_COUNT_MS+100)){hideEarnedFlight();scene.flightActive=false;}
}
if(typeof consumeCombatEvents==='function'){const spectacleConsume=consumeCombatEvents;consumeCombatEvents=function(events){spectacleConsume(events);syncCombatSpectacle(events);};}
const personalUpdate=update;update=function(){personalUpdate();syncPersonalResult();};
const personalDisplay=displayMultiState;displayMultiState=function(){personalDisplay();syncPersonalResult();};
const personalLoop=loop;loop=function(t){personalLoop(t);syncPersonalResult(t);};
// Optional cue uses the last 300ms of existing shared waiting time, otherwise the first frame; no delay is added.
const personalScreen=showScreen;showScreen=function(next){if(next!=='game'){cancelPersonalResult();cancelSpectacleAnimations();}personalScreen(next);syncPersonalResult();syncReactions();};
if(typeof document.addEventListener==='function')document.addEventListener('visibilitychange',()=>{if(document.hidden){cancelPersonalResult();cancelSpectacleAnimations();}});

// Endless double-up boundary controls. One choice per player after round ten.
let audioCashoutObserved=null;
const cashoutReceiptSeen=new Set();
function observeOwnCashoutAudio(){
 if(typeof battleAudio==='undefined'||typeof audioBattleKey!=='function')return;
 let row=null,playerId=null,sessionId=null;
 if(multiSession){
  const s=multiSnapshot;playerId=multiUser;sessionId=s?.sessionId;
  row=s?.wallets?.find(p=>p.playerId===playerId)||null;
 }else{
  playerId=PLAYER;sessionId=walletState?.sessionId;
  row=walletState?.players?.find(p=>p.playerId===playerId)||null;
 }
 if(!row||typeof row.cashedOut!=='boolean'||typeof sessionId!=='string'||!sessionId||typeof playerId!=='string'||!playerId)return;
 const key=audioBattleKey()+':'+playerId,now={key,cashedOut:row.cashedOut,reason:row.cashoutReason,amount:row.cashoutAmount};
 if(!audioCashoutObserved||audioCashoutObserved.key!==key){audioCashoutObserved=now;return;}
 const prior=audioCashoutObserved;audioCashoutObserved=now;
 // Play only on this viewer's observed canonical player cash-out transition.
 // Room-exit/no-prediction automation and already-cashed reconnects are silent.
 if(prior.cashedOut===false&&now.cashedOut===true&&now.reason==='player')audioCall(()=>battleAudio.playRunDecision(audioBattleKey(),'cashout',{
  reason:'player',amount:now.amount,playerId
 }));
}
function syncCashoutReceipt(){
 const node=document.querySelector('#cashoutReceipt');if(!node)return;
 const playerId=multiSession?multiUser:PLAYER,sessionId=multiSession?multiSnapshot?.sessionId:walletState?.sessionId;
 const row=multiSession?multiSnapshot?.wallets?.find(p=>p.playerId===playerId):walletState?.players?.find(p=>p.playerId===playerId);
 let amount=null;try{if(row?.cashedOut===true&&row.cashoutReason==='player')amount=Money.amountBig(row.cashoutAmount);}catch{}
 if(amount===null||amount<=0n){node.hidden=true;node.textContent='';return;}
 node.hidden=false;const text='終了額 · '+MoneyUI.balanceText(amount);if(node.textContent!==text)node.textContent=text;
 const key=[sessionId,playerId,row.cashoutRound,row.cashoutRequestId,amount.toString()].join(':');
 if(cashoutReceiptSeen.has(key))return;
 cashoutReceiptSeen.add(key);if(cashoutReceiptSeen.size>80)cashoutReceiptSeen.delete(cashoutReceiptSeen.values().next().value);
 if(typeof node.animate==='function'&&!(typeof matchMedia==='function'&&matchMedia('(prefers-reduced-motion: reduce)').matches)){try{node.animate([
  {transform:'translateY(3px) scale(.97)',opacity:.4},
  {transform:'translateY(-1px) scale(1.025)',opacity:1,offset:.56},
  {transform:'translateY(0) scale(1)',opacity:1}
 ],{duration:220,easing:'steps(4,end)'});}catch{}}
}
function setCashoutChoiceLabel(button,active=true){
 const label=active?'<span class="extension-choice-main">ここで終了</span>\n<span class="extension-choice-note">(ランキングに記録)</span>':'記録';
 if(button.innerHTML!==label)button.innerHTML=label;
}
function syncExtensionControls(){
 observeOwnCashoutAudio();
 syncCashoutReceipt();
 const choices=document.querySelector('#extensionChoices'),cash=document.querySelector('#cashOut'),cont=document.querySelector('#continueRun'),next=document.querySelector('#next'),net=document.querySelector('#checkpointNet');
 if(!choices||!cash||!cont||!next)return;
 if(net)net.hidden=true;
 const soloBoundary=!multiSession&&state==='result'&&soloTerminalBoundary();
 const s=multiSession?multiSnapshot:null;
 const multiBoundary=!!s&&s.phase==='result'&&s.roundId>=TOTAL_ROUNDS;
 const own=s?.wallets?.find(p=>p.playerId===multiUser),bankruptNotice=document.querySelector('#bankruptNotice');
 if(bankruptNotice){const broke=multiSession?own?.terminalReason==='bankrupt':soloBoundary&&SoloWallet.isBankrupt(walletState);bankruptNotice.hidden=!broke;bankruptNotice.textContent=broke?(multiSession?'残高0Gで予想終了。ほかの人の対戦は観戦できます。':'残高0Gで終了です。'):'';}
 if(multiBoundary){
  const own=s.wallets?.find(p=>p.playerId===multiUser),isParticipant=s.participants.includes(multiUser);
  const active=isParticipant&&own&&!own.cashedOut&&own.terminalReason!=='bankrupt'&&Money.amountBig(own.balance)>0n,canContinue=active&&Money.doubleAmountFits(own.balance);
  const embedded=!!globalThis.parent&&globalThis.parent!==globalThis,canRecord=!!(isParticipant&&own?.cashedOut&&embedded&&(gravityContext||nativeProfileVerified)&&!scoreBridge.hasAttempted(s.sessionId,multiUser)&&Money.amountBig(own.cashoutAmount)<=BigInt(Number.MAX_SAFE_INTEGER));
  choices.hidden=!active&&!canRecord;
  cash.hidden=!active&&!canRecord;cont.hidden=!canContinue;
  cash.disabled=!active&&!canRecord;
  setCashoutChoiceLabel(cash,active);
  cont.disabled=!canContinue||(s.continueIds||[]).includes(multiUser);
  if(cont.disabled&&canContinue)cont.textContent='選択済み';else cont.textContent='全額を賭けて挑戦';
  const ownTerminal=isParticipant&&own&&(own.cashedOut||own.terminalReason==='bankrupt');
  next.hidden=!ownTerminal;next.disabled=false;next.textContent='ホームに戻る';
  return;
 }
 if(soloBoundary&&!soloRunEnded){
  const canCash=SoloWallet.canCashOut(walletState,PLAYER),canContinue=SoloWallet.canContinueDoubleUp(walletState);
  const broke=SoloWallet.isBankrupt(walletState);
  choices.hidden=broke||(!canCash&&!canContinue);
  cash.hidden=!canCash;cont.hidden=!canContinue;
  setCashoutChoiceLabel(cash);cash.disabled=!canCash;cont.disabled=!canContinue;cont.textContent='全額を賭けて挑戦';
  next.hidden=!broke;next.disabled=false;next.textContent='ホームに戻る';
  return;
 }
 choices.hidden=true;cash.hidden=true;cont.hidden=true;
 if(!multiSession&&soloRunEnded&&state==='result'&&soloTerminalBoundary()){next.hidden=false;next.disabled=false;next.textContent='ホームに戻る';}
}

function continueSoloRun(){
 if(multiSession||state!=='result'||soloRunEnded||!SoloWallet.canContinueDoubleUp(walletState))return false;
 const before=walletState,requestId='doubleup:'+round;
 try{
  walletState=SoloWallet.continueDoubleUp(before,{sessionId:before.sessionId,roundId:round,requestId});
  nextPrediction();syncExtensionControls();return true;
 }catch(error){walletState=before;throw error;}
}

function continueMultiRun(){
 if(!multiSession||multiSnapshot?.phase!=='result'||round<TOTAL_ROUNDS)return false;
 const s=multiSession.getState(),own=s.wallets?.find(p=>p.playerId===multiUser);
 if(!own||own.cashedOut||own.terminalReason==='bankrupt'||Money.amountBig(own.balance)===0n)return false;
 return multiSession.requestContinue();
}

function cashOutRun(){
 if(multiSession){
  if(multiSnapshot?.phase!=='result'||round<TOTAL_ROUNDS)return false;
  const s=multiSession.getState(),own=s.wallets?.find(p=>p.playerId===multiUser);
  if(own?.cashedOut===true){void submitFinalScore('cashout',true);syncExtensionControls();return true;}
  pendingOwnCashoutPost=s.sessionId+'\u0000'+multiUser+'\u0000'+s.roundId;
  const ok=multiSession.cashOut('player');if(!ok)pendingOwnCashoutPost=null;syncExtensionControls();return ok;
 }
 if(state!=='result'||soloRunEnded||!SoloWallet.canCashOut(walletState,PLAYER))return false;
 walletState=SoloWallet.cashOut(walletState,{sessionId:walletState.sessionId,playerId:PLAYER,roundId:round,requestId:'cashout:'+round});
 soloRunEnded=true;void submitFinalScore('cashout',true);syncExtensionControls();return true;
}

function finishSoloRun(){
 if(multiSession||state!=='result'||!soloTerminalBoundary()||soloRunEnded||!SoloWallet.isBankrupt(walletState))return false;
 // A zero result is terminal but intentionally is not sent as a ranking score.
 soloRunEnded=true;syncExtensionControls();return true;
}

document.querySelector('#scoreRetry').onclick=()=>{const input=failedScoreInputs.get(failedScoreKey);if(input)attemptFinalScore({...input,userInitiated:true,automaticTimeout:false});};
document.querySelector('#roomScoreRetry').onclick=()=>document.querySelector('#scoreRetry').onclick();
document.querySelector('#cashOut').onclick=cashOutRun;
document.querySelector('#continueRun').onclick=()=>multiSession?continueMultiRun():continueSoloRun();
const extensionNext=document.querySelector('#next').onclick;
document.querySelector('#next').onclick=e=>{
 if(multiSession){
  const own=multiSnapshot?.wallets?.find(p=>p.playerId===multiUser);
  if(multiSnapshot?.phase==='result'&&round>=TOTAL_ROUNDS&&(own?.cashedOut||own?.terminalReason==='bankrupt')){showScreen('home');return;}
  if(round<TOTAL_ROUNDS)extensionNext(e);return;
 }
 if(soloRunEnded){showScreen('home');return;}
 if(state==='result'&&soloTerminalBoundary()&&SoloWallet.isBankrupt(walletState)){finishSoloRun();showScreen('home');return;}
 if(state==='result'&&soloTerminalBoundary())return;
 extensionNext(e);
};
const extensionUpdate=update;update=function(){extensionUpdate();syncExtensionControls();};
const extensionDisplay=displayMultiState;displayMultiState=function(){extensionDisplay();syncExtensionControls();};
const extensionLoop=loop;loop=function(t){extensionLoop(t);syncExtensionControls();};
syncExtensionControls();

