const BATTLE_LOG_LAUNCH=new Set('counter_bolt_release projectile_release pillar_release corner_pillar_release shockwave_release high_breath_release high_cleave_swing ground_burst cleave_release breath_release'.split(' '));
const BATTLE_LOG_COMPLETION=new Set('book_action_end defense_action_end aegis_action_end dispel_action_end melee_action_end combo_melee_end charged_shot_end moon_action_end orb_action_end pillar_action_end corner_pillar_end high_action_end wave4_action_end'.split(' '));
