const logAdvanceResultRead=advanceResultRead;advanceResultRead=function(t){if(battleLogOpen&&state==='result'){resultReadLast=t;return;}logAdvanceResultRead(t);};
const battleLogToggle=document.querySelector('#battleLog');if(battleLogToggle)battleLogToggle.onclick=()=>{if(state!=='result')setBattleLogOpen(!battleLogOpen,battleLogToggle);};
const battleLogClose=document.querySelector('#battleLogClose');if(battleLogClose)battleLogClose.onclick=()=>{setBattleLogOpen(false);battleLogReturnFocus?.focus?.();};
const battleLogPrevious=document.querySelector('#battleLogPrevious');if(battleLogPrevious)battleLogPrevious.onclick=()=>{const before=Number(battleLogPrevious.getAttribute('data-before'));if(before>0){battleLogPageEnd=before-1;battleLogScrollHold=false;syncBattleLog(performance.now(),true);const list=document.querySelector('#battleLogHistoryList');if(list)list.scrollTop=0;}};
const battleLogLatest=document.querySelector('#battleLogLatest');if(battleLogLatest)battleLogLatest.onclick=()=>{battleLogPageEnd=null;battleLogScrollHold=false;syncBattleLog(performance.now(),true);};
const battleLogList=document.querySelector('#battleLogHistoryList');if(battleLogList)battleLogList.onscroll=()=>{battleLogScrollHold=battleLogList.scrollHeight-battleLogList.clientHeight-battleLogList.scrollTop>24;if(battleLogScrollHold&&battleLogPageEnd===null){const rows=battleLogView().rows;battleLogPageEnd=rows[rows.length - 1]?.seq??null;}const latest=document.querySelector('#battleLogLatest');if(latest)latest.disabled=!battleLogScrollHold&&battleLogPageEnd===null;};
if(typeof document.addEventListener==='function')document.addEventListener('keydown',e=>{if(e.key==='Escape'&&battleLogOpen){e.preventDefault();setBattleLogOpen(false);battleLogReturnFocus?.focus?.();}});

const battleLogResult=document.querySelector('#battleLogResult');if(battleLogResult)battleLogResult.onclick=()=>setBattleLogOpen(!battleLogOpen,battleLogResult);

// terrain-result-clearance-20261108: DOM layout only; never a gameplay tick.
(function(){
  const screen=document.querySelector('#gameScreen'),header=document.querySelector('#gameTopline'),toolbar=document.querySelector('#gameToolbar');
  if(!screen||!header||!toolbar||typeof screen.style?.setProperty!=='function')return;
  const frame=typeof window.requestAnimationFrame==='function'?window.requestAnimationFrame.bind(window):fn=>fn();
  let queued=false,last='';
  function measure(){
    queued=false;
    if(screen.hidden||toolbar.hidden)return;
    const outer=screen.getBoundingClientRect(),upper=toolbar.getBoundingClientRect();
    if(!(outer.height>0&&upper.height>0)||!Number.isFinite(upper.bottom-outer.top))return;
    // Original clearance is 126px: upper stack + 8px gap + 8px bottom.
    // Preserve that minimum so normal-size result geometry cannot expand.
    const value=Math.max(126,Math.ceil(upper.bottom-outer.top+16))+'px';
    if(value!==last){last=value;screen.style.setProperty('--result-upper-clearance',value);}
  }
  function schedule(){if(!queued){queued=true;frame(measure);}}
  if(typeof window.ResizeObserver==='function'){
    const observer=new window.ResizeObserver(schedule);
    observer.observe(screen);observer.observe(header);observer.observe(toolbar);
  }else{
    // Older engines: watch only game visibility/phase and terrain text, never
    // the clock. Repeated writes of unchanged text do not request a layout read.
    const field=document.querySelector('#fieldStatus');
    let hidden=screen.hidden,phase=screen.getAttribute?.('data-phase'),text=field?.textContent;
    if(typeof window.MutationObserver==='function'){
      const observer=new window.MutationObserver(()=>{
        const nextHidden=screen.hidden,nextPhase=screen.getAttribute?.('data-phase'),nextText=field?.textContent;
        if(nextHidden===hidden&&nextPhase===phase&&nextText===text)return;
        hidden=nextHidden;phase=nextPhase;text=nextText;schedule();
      });
      observer.observe(screen,{attributes:true,attributeFilter:['hidden','data-phase']});
      if(field)observer.observe(field,{childList:true,characterData:true,subtree:true});
    }
    // Font completion can change wrapping without changing the terrain string.
    document.fonts?.ready?.then?.(schedule,()=>{});
    document.fonts?.addEventListener?.('loadingdone',schedule);
  }
  window.addEventListener?.('resize',schedule,{passive:true});
  window.addEventListener?.('pageshow',schedule);
  measure();
}());

requestAnimationFrame(loop);
if(typeof window!=='undefined'&&window.__gameBootComplete)window.__gameBootComplete();
